fn solve(n: i8) -> Vec<i8> {
    match n % 3 {
        0 => {
            // n is divisible by 3
            let a = n / 3;
            vec![a, 0, 0]
        }
        1 => {
            // n ≡ 1 (mod 3)
            if n < 7 {
                // too small to form 1 with non‐negative 3a+5b+7c
                vec![-1]
            } else {
                // use one 7 and fill the rest with 3's
                let a = (n - 7) / 3;
                vec![a, 0, 1]
            }
        }
        _ => {
            // n ≡ 2 (mod 3)
            if n < 5 {
                // too small to form 2 with non‐negative 3a+5b+7c
                vec![-1]
            } else {
                // use one 5 and fill the rest with 3's
                let a = (n - 5) / 3;
                vec![a, 1, 0]
            }
        }
    }
}

